import React from 'react';
import {
  TrendingUp, TrendingDown, DollarSign, Users,
  ShoppingCart, Package, CreditCard, Clock
} from 'lucide-react';

const StatisticsCards = ({ timeRange }) => {
  const stats = [
    {
      title: 'Revenu total',
      value: '€124,850',
      change: '+15.2%',
      trend: 'up',
      icon: <DollarSign className="h-5 w-5" />,
      color: 'from-emerald-500 to-teal-400'
    },
    {
      title: 'Nouveaux utilisateurs',
      value: '2,458',
      change: '+8.7%',
      trend: 'up',
      icon: <Users className="h-5 w-5" />,
      color: 'from-blue-500 to-cyan-400'
    },
    {
      title: 'Commandes',
      value: '1,248',
      change: '+12.4%',
      trend: 'up',
      icon: <ShoppingCart className="h-5 w-5" />,
      color: 'from-purple-500 to-pink-400'
    },
    {
      title: 'Panier moyen',
      value: '€98.50',
      change: '+5.3%',
      trend: 'up',
      icon: <Package className="h-5 w-5" />,
      color: 'from-amber-500 to-orange-400'
    }
  ];

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
      {stats.map((stat, index) => (
        <div 
          key={index}
          className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-lg border border-white/40 dark:border-neutral-800/60 p-6 hover:scale-[1.02] transition-all duration-300 group"
        >
          <div className="flex items-center justify-between mb-4">
            <div className={`h-12 w-12 rounded-2xl bg-gradient-to-r ${stat.color} flex items-center justify-center shadow-lg`}>
              <div className="text-white">
                {stat.icon}
              </div>
            </div>
            <div className={`flex items-center px-2 py-1 rounded-lg ${
              stat.trend === 'up' 
                ? 'bg-green-500/10 text-green-600 dark:text-green-400' 
                : 'bg-red-500/10 text-red-600 dark:text-red-400'
            }`}>
              {stat.trend === 'up' ? (
                <TrendingUp className="h-3 w-3 mr-1" />
              ) : (
                <TrendingDown className="h-3 w-3 mr-1" />
              )}
              <span className="text-sm font-medium">{stat.change}</span>
            </div>
          </div>

          <h4 className="text-2xl font-bold text-neutral-900 dark:text-white mb-2">
            {stat.value}
          </h4>
          <p className="text-sm text-neutral-600 dark:text-neutral-400">
            {stat.title}
          </p>

          <div className="mt-4 pt-4 border-t border-neutral-200 dark:border-neutral-800">
            <div className="flex items-center justify-between">
              <span className="text-xs text-neutral-500 dark:text-neutral-500">Cette {timeRange}</span>
              <div className="flex items-center text-primary-600 dark:text-primary-400 cursor-pointer group-hover:translate-x-1 transition-transform duration-300">
                <span className="text-xs">Voir détails</span>
                <Clock className="h-3 w-3 ml-1" />
              </div>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

export default StatisticsCards;
